def compute(vars):
    revenue = vars["Revenue"]
    cost_of_sales = vars["Cost of Sales"]

    gross_profit = None
    if revenue is not None and cost_of_sales is not None:
        gross_profit = revenue - cost_of_sales

    return {
        "value": gross_profit,
        "trace": {
            "Revenue": revenue,
            "Cost of Sales": cost_of_sales,
            "Gross Profit": gross_profit,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
